use actix_web::{web, App, HttpServer, HttpResponse, HttpRequest};
use serde::Deserialize;
use std::process::Command;

#[derive(Deserialize)]
struct DiagRequest {
    target: String,
    mode: Option<String>,
}

/// Network diagnostic endpoint used by internal monitoring dashboards.
/// Performs connectivity checks to specified targets.
async fn network_diag(query: web::Query<DiagRequest>) -> HttpResponse {
    let target = &query.target;
    let mode = query.mode.as_deref().unwrap_or("ping");

    // Validate mode parameter
    let allowed_modes = ["ping", "traceroute", "dns"];
    if !allowed_modes.contains(&mode) {
        return HttpResponse::BadRequest().body("Invalid diagnostic mode");
    }

    // Build command based on mode
    let output = match mode {
        "ping" => {
            Command::new("/bin/sh")
                .arg("-c")
                .arg(format!("ping -c 3 -W 5 {}", target))
                .output()
        }
        "traceroute" => {
            Command::new("/bin/sh")
                .arg("-c")
                .arg(format!("traceroute -m 10 {}", target))
                .output()
        }
        "dns" => {
            Command::new("/bin/sh")
                .arg("-c")
                .arg(format!("dig +short {}", target))
                .output()
        }
        _ => unreachable!()
    };

    match output {
        Ok(result) => {
            let stdout = String::from_utf8_lossy(&result.stdout);
            let stderr = String::from_utf8_lossy(&result.stderr);
            HttpResponse::Ok().json(serde_json::json!({
                "status": result.status.code(),
                "stdout": stdout,
                "stderr": stderr,
                "target": target,
                "mode": mode
            }))
        }
        Err(e) => {
            HttpResponse::InternalServerError().body(format!("Execution failed: {}", e))
        }
    }
}

/// Health check endpoint
async fn health() -> HttpResponse {
    HttpResponse::Ok().json(serde_json::json!({"status": "healthy"}))
}

/// Metrics endpoint for Prometheus scraping
async fn metrics() -> HttpResponse {
    HttpResponse::Ok()
        .content_type("text/plain")
        .body("# HELP diag_requests_total Total diagnostic requests\ndiag_requests_total 0\n")
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    env_logger::init();
    log::info!("Starting network diagnostic service on :8080");

    HttpServer::new(|| {
        App::new()
            .route("/diag", web::get().to(network_diag))
            .route("/health", web::get().to(health))
            .route("/metrics", web::get().to(metrics))
    })
    .bind("0.0.0.0:8080")?
    .workers(2)
    .run()
    .await
}
